    name: String,
    color: String,
) -> ResultWithDefaultError<Project> {
    let url = format!("{}/workspaces/{}/projects", self.base_url, workspace_id);
    let body = NetworkCreateProject {
        name,
        workspace_id,
        color,
        is_private: false,
        active: true,
