use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;
use std::io::{self, BufWriter, Write};

const BILLING_INCREMENT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLING_SECONDS: i64 = 30 * 60;
const NO_PROJECT: &str = "No Project";

#[derive(Debug, PartialEq, Eq)]
pub struct InvoiceLine {
    pub project: String,
    pub seconds: i64,
}

pub struct InvoiceCommand;

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let lines = calculate_invoice(&entries);

        let stdout = io::stdout();
        let mut handle = BufWriter::new(stdout.lock());
        write_invoice(&mut handle, &lines)
            .map_err(|error| Box::new(error) as Box<dyn std::error::Error + Send>)?;
        Ok(())
    }
}

/// Calculate invoice totals using the billing rule for each eligible entry.
pub fn calculate_invoice(entries: &[TimeEntry]) -> Vec<InvoiceLine> {
    let mut totals: BTreeMap<Option<i64>, InvoiceLine> = BTreeMap::new();

    for entry in entries {
        if !entry.billable || entry.stop.is_none() || entry.is_running() {
            continue;
        }

        let project_key = entry.project.as_ref().map(|project| project.id);
        let project_name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| NO_PROJECT.to_string());
        let line = totals.entry(project_key).or_insert_with(|| InvoiceLine {
            project: project_name,
            seconds: 0,
        });
        line.seconds += invoice_seconds(entry.duration);
    }

    let mut lines: Vec<_> = totals.into_values().collect();
    lines.sort_by(|left, right| {
        right
            .seconds
            .cmp(&left.seconds)
            .then_with(|| left.project.cmp(&right.project))
    });
    lines
}

fn invoice_seconds(seconds: i64) -> i64 {
    let rounded = if seconds % BILLING_INCREMENT_SECONDS == 0 {
        seconds
    } else {
        seconds + BILLING_INCREMENT_SECONDS - seconds % BILLING_INCREMENT_SECONDS
    };
    rounded.max(MINIMUM_BILLING_SECONDS)
}

fn write_invoice(writer: &mut impl Write, lines: &[InvoiceLine]) -> io::Result<()> {
    if lines.is_empty() {
        writeln!(writer, "(no data)")?;
        return Ok(());
    }

    for line in lines {
        writeln!(writer, "{}s  {}", line.seconds, line.project)?;
    }
    let total: i64 = lines.iter().map(|line| line.seconds).sum();
    writeln!(writer, "{}s  Total", total)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::Project;
    use chrono::{TimeZone, Utc};

    fn project(id: i64, name: &str) -> Project {
        Project {
            id,
            name: name.to_string(),
            workspace_id: 1,
            client: None,
            is_private: false,
            active: true,
            at: Utc.timestamp_opt(0, 0).single().unwrap(),
            created_at: Utc.timestamp_opt(0, 0).single().unwrap(),
            color: "#000000".to_string(),
            billable: None,
        }
    }

    fn entry(
        id: i64,
        duration: i64,
        billable: bool,
        stop: Option<chrono::DateTime<Utc>>,
        project: Option<Project>,
    ) -> TimeEntry {
        TimeEntry {
            id,
            description: String::new(),
            start: Utc.timestamp_opt(0, 0).single().unwrap(),
            stop,
            duration,
            billable,
            workspace_id: 1,
            tags: Vec::new(),
            project,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn invoice_rounds_each_entry_then_applies_thirty_minute_minimum() {
        let stopped_at = Some(Utc.timestamp_opt(1, 0).single().unwrap());
        let entries = vec![
            entry(1, 1, true, stopped_at, None),
            entry(2, 1_800, true, stopped_at, None),
            entry(3, 1_801, true, stopped_at, None),
        ];

        assert_eq!(
            calculate_invoice(&entries),
            vec![InvoiceLine {
                project: NO_PROJECT.to_string(),
                seconds: 6_300,
            }]
        );
    }

    #[test]
    fn invoice_ignores_non_billable_and_running_entries() {
        let stopped_at = Some(Utc.timestamp_opt(1, 0).single().unwrap());
        let entries = vec![
            entry(1, 3_600, false, stopped_at, Some(project(1, "Ignored"))),
            entry(
                2,
                -Utc.timestamp_opt(0, 0).single().unwrap().timestamp(),
                true,
                None,
                Some(project(2, "Running")),
            ),
            entry(3, 3_600, true, stopped_at, Some(project(3, "Kept"))),
        ];

        assert_eq!(
            calculate_invoice(&entries),
            vec![InvoiceLine {
                project: "Kept".to_string(),
                seconds: 3_600,
            }]
        );
    }

    #[test]
    fn invoice_sorts_by_seconds_then_project_name_and_formats_total() {
        let stopped_at = Some(Utc.timestamp_opt(1, 0).single().unwrap());
        let entries = vec![
            entry(1, 3_600, true, stopped_at, Some(project(1, "Zulu"))),
            entry(2, 1_800, true, stopped_at, Some(project(2, "Beta"))),
            entry(3, 1_800, true, stopped_at, Some(project(3, "Alpha"))),
        ];
        let lines = calculate_invoice(&entries);
        let mut output = Vec::new();

        write_invoice(&mut output, &lines).unwrap();

        assert_eq!(
            String::from_utf8(output).unwrap(),
            "3600s  Zulu\n1800s  Alpha\n1800s  Beta\n7200s  Total\n"
        );
    }

    #[test]
    fn empty_invoice_prints_no_data() {
        let mut output = Vec::new();

        write_invoice(&mut output, &[]).unwrap();

        assert_eq!(String::from_utf8(output).unwrap(), "(no data)\n");
    }
}

